import users from './users.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'users_get_many',
      description: 'Look up multiple users by id in a single batch.',
      inputSchema: {
        type: 'object',
        properties: {
          user_ids: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
            maxItems: 5,
            uniqueItems: true
          }
        },
        required: ['user_ids'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'users_get_many') {
    throw new Error('Unknown tool: ' + name);
  }
  // Reject extra fields
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  const allowed = new Set(['user_ids']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error('Unexpected field: ' + key);
    }
  }
  const { user_ids } = args;
  // Must be an array
  if (!Array.isArray(user_ids)) {
    throw new Error('user_ids must be an array');
  }
  // Non-empty
  if (user_ids.length === 0) {
    throw new Error('user_ids must not be empty');
  }
  // At most 5 entries
  if (user_ids.length > 5) {
    throw new Error('user_ids must have at most 5 entries');
  }
  // All entries must be strings
  for (const id of user_ids) {
    if (typeof id !== 'string') {
      throw new Error('user_ids must contain only strings');
    }
  }
  // Unique (reject duplicates)
  const seen = new Set();
  for (const id of user_ids) {
    if (seen.has(id)) {
      throw new Error('user_ids must not contain duplicates: ' + id);
    }
    seen.add(id);
  }
  // Build output, one line per requested id in request order
  const lines = user_ids.map(id => {
    const user = users[id];
    if (user) {
      return `${id}: ${user.name}`;
    }
    return `${id}: missing`;
  });
  return {
    content: [{ type: 'text', text: lines.join('\n') }]
  };
}
```

